<script lang="ts">import Shell from '$lib/components/Shell.svelte';import {GitBranch,ZoomIn,ZoomOut,Maximize,MousePointer2} from 'lucide-svelte';let {data}=$props();const d=data.snapshot;let selected=$state<any>(null);let scale=$state(1);const cols:any={sale:0,fee:1,refund:1,dispute:1,fx_conversion:2,payout:3,bank_deposit:4};const labels:any={sale:'Sales',fee:'Adjustments',refund:'Adjustments',dispute:'Adjustments',fx_conversion:'FX',payout:'Payouts',bank_deposit:'Bank'};const positions=new Map();const rows=new Map();for(const e of d.events){const c=cols[e.kind];const r=rows.get(c)??0;rows.set(c,r+1);positions.set(e.id,{x:45+c*210,y:75+r*88})}const money=(e:any)=>new Intl.NumberFormat('en-US',{style:'currency',currency:e.currency}).format(e.amount/100);const related=()=>selected?d.edges.filter((e:any)=>e.fromEventId===selected.id||e.toEventId===selected.id):[];</script>
<Shell><div class="graph-page"><header class="page-head"><div><p class="eyebrow">Money map</p><h1>Sale to bank</h1><p>Follow every economic relationship across processors, adjustments, payouts, and deposits.</p></div><span class="status-pill"><i></i>{d.edges.filter((e:any)=>e.status!=='rejected').length} active connections</span></header>{#if !d.events.length}<div class="empty"><GitBranch/><h2>No money map yet</h2><p>Import data and run reconciliation from Overview first.</p></div>{:else}<div class="legend"><span><i class="auto"></i>Auto / approved</span><span><i class="review"></i>Needs review</span><span class="hint"><MousePointer2 size={13}/>Select an event to inspect it</span></div><div class="graph-layout"><div class="canvas card"><div class="tools"><button onclick={()=>scale=Math.min(1.4,scale+.1)} aria-label="Zoom in"><ZoomIn/></button><button onclick={()=>scale=Math.max(.6,scale-.1)} aria-label="Zoom out"><ZoomOut/></button><button onclick={()=>scale=1} aria-label="Reset zoom"><Maximize/></button></div><div class="stage" style:transform={`scale(${scale})`}><div class="columns">{#each ['Sales','Adjustments','FX','Payouts','Bank'] as l}<span>{l}</span>{/each}</div><svg aria-hidden="true" viewBox="0 0 950 590" preserveAspectRatio="none">{#each d.edges.filter((x:any)=>x.status!=='rejected') as edge}{@const a=positions.get(edge.fromEventId)}{@const b=positions.get(edge.toEventId)}{#if a&&b}<path d={`M${a.x+155},${a.y+29} C${a.x+180},${a.y+29} ${b.x-25},${b.y+29} ${b.x},${b.y+29}`} class:review={edge.status==='review'}/>{/if}{/each}</svg>{#each d.events as e}{@const p=positions.get(e.id)}<button class="node {e.source}" class:selected={selected?.id===e.id} style:left={`${p.x}px`} style:top={`${p.y}px`} onclick={()=>selected=e}><span>{e.source} · {e.kind.replace('_',' ')}</span><strong>{money(e)}</strong><small>{e.occurredAt.slice(0,10)}</small></button>{/each}</div></div><aside class="inspector card">{#if selected}<header><span class="chip">{selected.source}</span><h2>{selected.kind.replace('_',' ')}</h2><strong>{money(selected)}</strong></header><dl><div><dt>Event ID</dt><dd>{selected.id}</dd></div><div><dt>Occurred</dt><dd>{selected.occurredAt.slice(0,10)}</dd></div><div><dt>External reference</dt><dd>{selected.externalRef??'—'}</dd></div><div><dt>Payout reference</dt><dd>{selected.payoutRef??'—'}</dd></div></dl><section><h3>Connections</h3>{#if !related().length}<p>No active connections.</p>{:else}{#each related() as edge}<article><b>{edge.relationship.replace('_',' ')}</b><span class:warn={edge.status==='review'}>{edge.status} · {(edge.confidence*100).toFixed(0)}%</span><small>{edge.reasons.join(' · ')}</small></article>{/each}{/if}</section>{:else}<div class="inspect-empty"><MousePointer2/><h2>Select an event</h2><p>Inspect references, confidence, status, and matching evidence.</p></div>{/if}</aside></div>{/if}</div></Shell>
<style>.graph-page{display:flex;flex-direction:column;gap:22px}.legend{display:flex;gap:22px;font-size:10px;color:var(--muted)}.legend span{display:flex;align-items:center;gap:6px}.legend i{width:18px;height:2px;background:var(--green)}.legend i.review{background:var(--amber);border-top:1px dashed white}.legend .hint{margin-left:auto}.graph-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:18px}.canvas{height:650px;overflow:auto;position:relative;background-color:#fafbf8;background-image:radial-gradient(#d7ddd7 1px,transparent 1px);background-size:20px 20px}.stage{position:relative;width:980px;height:610px;transform-origin:top left;transition:transform .15s}.columns{position:absolute;top:22px;left:45px;right:0;display:grid;grid-template-columns:repeat(5,210px);font:9px 'DM Mono';text-transform:uppercase;letter-spacing:.11em;color:#8c968f}.stage svg{position:absolute;inset:0;width:950px;height:590px;overflow:visible}.stage path{fill:none;stroke:var(--green);stroke-width:1.5}.stage path.review{stroke:var(--amber);stroke-dasharray:5 4}.node{position:absolute;width:155px;height:59px;text-align:left;border:1px solid #d7ded7;border-left:3px solid var(--green);border-radius:8px;background:#fff;padding:8px 10px;box-shadow:0 3px 9px rgba(16,25,20,.05)}.node.stripe{border-left-color:#635bff}.node.gumroad{border-left-color:#dc60c5}.node.dodo{border-left-color:#c99625}.node.bank{border-left-color:#117aca}.node.selected{outline:3px solid rgba(31,104,72,.18);border-color:var(--green)}.node span,.node small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font:7px 'DM Mono';text-transform:uppercase;color:var(--muted)}.node strong{display:block;font:500 11px 'DM Mono';margin:6px 0}.tools{position:sticky;z-index:5;top:12px;left:12px;width:34px;display:grid;background:#fff;border:1px solid var(--line);border-radius:7px;overflow:hidden}.tools button{width:32px;height:32px;background:#fff;border:0;border-bottom:1px solid var(--line)}.tools button:last-child{border:0}.tools svg{width:14px}.inspector{padding:19px;min-height:400px}.inspector header{border-bottom:1px solid var(--line);padding-bottom:17px}.inspector h2{text-transform:capitalize;font-size:17px;margin:13px 0 8px}.inspector header strong{font:500 22px 'DM Mono'}.inspector dl{display:grid;gap:14px;margin:20px 0}.inspector dt,.inspector h3{font:9px 'DM Mono';text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.inspector dd{font:10px 'DM Mono';margin:4px 0;overflow-wrap:anywhere}.inspector section{border-top:1px solid var(--line);padding-top:15px}.inspector article{display:grid;gap:5px;border:1px solid var(--line);padding:10px;margin-top:8px;border-radius:7px}.inspector article b{font-size:11px;text-transform:capitalize}.inspector article span{font:9px 'DM Mono';color:var(--green)}.inspector article small{color:var(--muted);line-height:1.5}.inspect-empty{text-align:center;padding:90px 10px;color:var(--muted)}.inspect-empty h2{color:var(--ink);margin-top:15px}.inspect-empty p{font-size:12px;line-height:1.5}@media(max-width:1100px){.graph-layout{grid-template-columns:1fr}.inspector{min-height:200px}.canvas{height:550px}}</style>
